"""Present the selected first-minute low/revisit examples without trade claims."""
from pathlib import Path
from datetime import datetime
import html
import json

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / 'reports/mnq-first-candle-chop-2026-10-28'
meta = json.loads((OUT / 'examples.json').read_text(encoding='utf-8'))
examples = meta['examples']
assert len(examples) == 3
assert meta['reference_known_et'] == '09:31'
CATEGORIES = {'up':'Later upward departure','down':'Later downward departure','unresolved':'No two-close departure by 09:45'}

def esc(value): return html.escape(str(value), quote=True)
def price(value):
    return f'{value:,.2f}' if round(value,2) == value else f'{value:,.3f}'

cards = []
nav = []
for i, e in enumerate(examples, 1):
    for key in ['png','svg','data_csv']:
        assert (OUT / e[key]).is_file(), e[key]
    assert e['first_candle_minutes'] == 1
    assert e['illustrative_lower_zone_fraction'] == .2
    date = datetime.strptime(e['date'],'%Y-%m-%d').strftime('%B %d, %Y').replace(' 0',' ')
    nav.append(f'<a href="#{esc(e["id"])}"><span>0{i}</span>{esc(CATEGORIES[e["category"]])}</a>')
    pairs = ''.join(f'<span><b>LOW {j}</b> {c["visit_minute_et"]} <em>→</em> <b>MID {j}</b> {c["bounce_minute_et"]}</span>' for j,c in enumerate(e['cycles'],1))
    levels = [('First low', e['first_low']), ('Lower-zone top', e['lower_zone_high']), ('Midpoint reference',e['midpoint']), ('First high',e['first_high'])]
    levels_html = ''.join(f'<div><dt>{label}</dt><dd>{price(value)}</dd></div>' for label,value in levels)
    alt = f'{e["date"]} MNQ opening candles: {e["title"]}. First minute from 09:30 to 09:31, lower-zone visits and later midpoint reaches marked.'
    cards.append(f'''
<article class="chart-card" id="{esc(e['id'])}">
  <div class="card-heading"><span class="category {e['category']}">{esc(CATEGORIES[e['category']])}</span><span class="date">{date}</span><h2>{esc(e['title'])}</h2><p>{esc(e['narrative'])}</p></div>
  <div class="chart-frame" tabindex="0" aria-label="Scrollable chart for {esc(date)}"><a href="{esc(e['svg'])}" target="_blank" rel="noopener" aria-label="Open full-size chart for {esc(date)}"><img src="{esc(e['png'])}" alt="{esc(alt)}" loading="lazy" decoding="async"></a></div>
  <div class="caption"><div class="pair-label">Observed visit minute → later midpoint minute</div><div class="pairs">{pairs}</div><p class="break-note">{esc(e['break_note'])}</p><dl class="levels">{levels_html}</dl><div class="links"><a href="{esc(e['svg'])}" target="_blank" rel="noopener">Open full-size chart</a><a href="{esc(e['png'])}" download>Save PNG</a><a href="{esc(e['data_csv'])}" download>15 observed candles · CSV</a></div></div>
</article>''')

for key in ['overview_png','overview_svg']:
    assert (OUT / meta[key]).is_file()

css='''
:root{color-scheme:dark;--bg:#0b141c;--panel:#101d27;--ink:#e8f0f6;--muted:#9db1c0;--line:#2a3c49;--blue:#68afff;--green:#36c3a7;--amber:#ffc163}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1260px;margin:30px auto;padding:0 22px 28px}header{border:1px solid var(--line);background:linear-gradient(125deg,#172e3c,#101d27 70%);border-radius:14px;padding:30px 34px}.eyebrow{color:var(--blue);font-size:11px;font-weight:750;letter-spacing:.13em}h1{font-size:37px;line-height:1.17;letter-spacing:-.025em;margin:11px 0 14px}header p{max-width:1040px;margin:0;color:#c7d7e2}.reference{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:19px;font-size:13px;color:var(--muted)}.reference strong{border:1px solid #466b88;color:var(--blue);padding:6px 12px;border-radius:6px}.guide{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:22px 0}.guide>div{padding:19px 22px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.guide h2{font-size:16px;color:var(--green);margin:0 0 8px}.guide p{margin:0;font-size:14px}.small{font-size:12px;color:var(--muted);line-height:1.65}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:20px 0}nav a{display:flex;align-items:center;gap:12px;padding:14px 17px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--ink);text-decoration:none;font-size:13px}nav a:hover{border-color:var(--blue)}nav span{font-size:12px;font-weight:750;color:var(--blue)}.overview{border:1px solid var(--line);border-radius:9px;background:var(--panel);padding:16px 21px;margin:20px 0}.overview summary{font-size:14px;font-weight:650;cursor:pointer}.overview p{margin-bottom:0}.overview .chart-frame{margin:16px -21px 0}.chart-card{border:1px solid var(--line);border-radius:12px;background:var(--panel);overflow:hidden;margin:25px 0;scroll-margin-top:18px}.card-heading{padding:22px 27px 19px}.category{display:inline-block;color:var(--green);background:#18372f;font-size:11px;letter-spacing:.025em;font-weight:750;border-radius:5px;padding:4px 9px}.category.down{color:#ff9ca7;background:#3b242d}.category.unresolved{color:var(--amber);background:#3a3120}.date{float:right;font-size:13px;color:var(--muted);padding-top:4px}h2{font-size:25px;line-height:1.3;margin:12px 0 9px}.card-heading p{font-size:14px;margin:0;color:#c7d7e2}.chart-frame{overflow-x:auto;background:#0f1921;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.chart-frame a{display:block}.chart-frame img{display:block;width:100%;height:auto;min-width:1000px}.caption{padding:20px 27px 23px}.pair-label{color:var(--muted);font-size:11px;letter-spacing:.04em}.pairs{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0 15px}.pairs span{background:#192b36;border:1px solid #2a4453;padding:8px 12px;border-radius:6px;font-size:13px;font-variant-numeric:tabular-nums}.pairs b{font-size:10px;letter-spacing:.04em;color:var(--green);margin-right:3px}.pairs b:nth-of-type(2){color:var(--amber)}.pairs em{font-style:normal;color:var(--muted);margin:0 8px}.break-note{font-size:14px;border-left:3px solid var(--amber);padding:5px 0 5px 14px;margin:15px 0 20px;color:#d3dfe6}.levels{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:0}.levels dt{font-size:11px;color:var(--muted)}.levels dd{font-size:17px;font-weight:700;margin:5px 0 0;font-variant-numeric:tabular-nums}.links{display:flex;flex-wrap:wrap;gap:20px;font-size:12px;margin-top:18px}a{color:var(--blue)}.method{padding:23px 27px;border:1px solid var(--line);border-radius:10px;background:var(--panel);margin-top:26px}.method h2{font-size:23px;margin-top:0}.method p{font-size:14px;color:#c7d7e2}.method ul{padding-left:22px;font-size:14px;color:#c7d7e2}.method li{margin:10px 0}.method strong{color:var(--ink)}footer{text-align:center;color:var(--muted);font-size:12px;padding:20px 3px 0}@media(max-width:850px){main{margin:14px auto;padding:0 12px 20px}header{padding:24px 22px}h1{font-size:30px}.guide{grid-template-columns:1fr;gap:12px}.guide>div{padding:17px 20px}nav{grid-template-columns:1fr;gap:8px}nav a{padding:11px 16px}.card-heading{padding:20px 20px 17px}.date{float:none;display:block;margin-top:10px}.card-heading h2{font-size:22px}.caption{padding:18px 20px 22px}.levels{grid-template-columns:repeat(2,1fr);gap:17px}.links{gap:11px 18px}.method{padding:22px}.chart-frame{scrollbar-width:thin}.pairs{display:grid;grid-template-columns:1fr}.pairs span{width:max-content;max-width:100%}.method h2{font-size:21px}}@media print{body{background:var(--bg);print-color-adjust:exact}main{max-width:none;margin:0;padding:0}header{padding:20px}h1{font-size:25pt}nav,.overview{display:none}.guide{gap:12px}.guide>div{padding:12px 16px}.chart-card{break-inside:avoid}.chart-frame{overflow:visible}.chart-frame img{min-width:0;width:100%}.card-heading{padding:15px 20px}.card-heading h2{font-size:16pt}.caption{padding:12px 20px}.links{display:none}.pairs span,.break-note{font-size:9pt}.levels dd{font-size:11pt}footer{font-size:8pt}@page{size:letter landscape;margin:12mm}}
'''

document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MNQ — Chop Around the First Candle’s Low</title><style>{css}</style></head><body><main>
<header><div class="eyebrow">MNQ / FIRST ONE-MINUTE CANDLE</div><h1>Chop around the first candle’s low</h1><p>Your idea is to look for a long near the lower edge of the first candle, expecting a bounce while price is moving back and forth. These real sessions show later low-zone revisits, later moves toward the middle, and what happened afterward.</p><div class="reference"><strong>First candle: 09:30–09:31 ET</strong><span>Its completed high and low are available at 09:31.</span></div></header>
<div class="guide"><div><h2>What the green zone shows</h2><p>The lower 20% of the completed first candle’s range is a visual guide for “near the bottom.” <b>LOW</b> marks a later visit; <b>MID</b> marks a strictly later minute that reaches the midpoint. These are price observations, not entries or trade results.</p></div><div><h2>What the later break marker shows</h2><p>Two consecutive closes outside the first candle’s range provide an illustration of a later departure. The marker becomes known only after the second candle ends. It is not a validated rule for when the market has “decided.”</p></div></div>
<p class="small">No entry is required to wait for its current candle to close. The first candle must finish to define its range; the later close-based marker is only an illustration. On smaller screens, swipe a chart sideways or open its full-size version.</p>
<nav aria-label="Selected sessions">{''.join(nav)}</nav>
<details class="overview"><summary>Compare all three sessions in one image</summary><div class="chart-frame" tabindex="0" aria-label="Scrollable three-session overview"><a href="{esc(meta['overview_svg'])}" target="_blank" rel="noopener"><img src="{esc(meta['overview_png'])}" alt="Three actual MNQ opening sessions showing repeated revisits near the first candle low and later midpoint reaches." loading="lazy" decoding="async"></a></div><p class="small"><a href="{esc(meta['overview_svg'])}" target="_blank" rel="noopener">Open full-size overview</a> · <a href="{esc(meta['overview_png'])}" download>Save overview PNG</a></p></details>
{''.join(cards)}
<section class="method" id="method"><h2>What these examples establish</h2><p>They illustrate the pattern you described using actual one-minute candles from 09:30 through 09:44. The 09:45 line is a cutoff, not an inferred price.</p><ul><li><strong>The examples were selected in hindsight.</strong> Repeated bounces and later persistence were not known at the first low-zone visit. This is not a frequency study, backtest or count of winning trades.</li><li><strong>The markings are illustrative.</strong> The lower fifth, midpoint and two-close departure are choices for showing the pattern clearly, not chosen or validated trading parameters. The midpoint and zone edges can fall between tradable ticks.</li><li><strong>A later bounce is not a fill.</strong> A visit candle overlaps the lower zone, and a strictly later candle reaches the midpoint with its high. Price can fall below the first low before returning. A later midpoint reach does not prove that a long trade would survive the intervening move. Times name whole-minute intervals; no executed long or profitable trade is established.</li><li><strong>No stop or executed entry is shown.</strong> The unresolved example means no two-close departure occurred before the cutoff; it does not guarantee the next move remains inside the range.</li></ul><p class="small">Each image links to its 15 observed candles. <a href="examples.json" download>Download the example definitions</a>. <a href="https://databento.com/docs/schemas/ohlcv">Databento’s OHLCV schema</a> documents the minute-bar fields and timestamps.</p></section>
<footer>Selected real MNQ sessions · All times Eastern · First-candle reference available at 09:31</footer></main></body></html>'''
(OUT/'index.html').write_text(document,encoding='utf-8')
print(json.dumps({'html':str(OUT/'index.html'),'examples':len(examples),'theme':'dark'}))
